html:
{%- set audience = "client" -%}{{ ia_report_guard(audience) }}
{%- set r = get_report_context(doc, None, True, audience) -%}
{%- set t = r.t -%}
{%- set brand = get_brand(True) -%}
{%- set rtl = r.dir == "rtl" -%}
{%- set S = "right" if rtl else "left" -%}
{%- set E = "left" if rtl else "right" -%}
{%- set ns = namespace(n=0) -%}
{%- macro k() -%}{%- set ns.n = ns.n + 1 -%}{{ "%02d"|format(ns.n) }}{%- endmacro -%}
<style>
{% if rtl %}{{ arabic_font_css() }}{% endif %}
.iamr{font-family:{% if rtl %}'IAM Arabic',{% endif %}"Helvetica Neue",Helvetica,Arial,sans-serif;color:{{ brand.ink }};font-size:10.5px;line-height:{{ 1.6 if rtl else 1.4 }};direction:{{ r.dir }};text-align:{{ S }}}
.iamr h1{font-size:22px;margin:0 0 4px;font-weight:{{ 700 if rtl else 600 }}}
.iamr h2{font-size:14px;margin:16px 0 6px;font-weight:{{ 700 if rtl else 600 }};border-bottom:1px solid #D7E0E5;padding-bottom:4px}
.iamr h2 .k{color:{{ brand.primary }};font-size:11px;font-weight:500;margin-{{ E }}:6px}
.iamr .eyebrow{font-size:9.5px;{% if not rtl %}letter-spacing:.1em;text-transform:uppercase;{% endif %}color:{{ brand.primary }};font-weight:600}
.iamr .muted{color:#586976}
.iamr table{direction:{{ r.dir }}}
.iamr table.t{width:100%;border-collapse:collapse;margin-top:4px}
.iamr table.t th{font-size:{{ 9.5 if rtl else 8.5 }}px;{% if not rtl %}letter-spacing:.06em;text-transform:uppercase;{% endif %}color:#586976;text-align:{{ S }};background:#F3F6F7;padding:5px 7px;border-bottom:1px solid #D7E0E5}
.iamr table.t td{padding:4px 7px;border-bottom:1px solid #E6ECEF;vertical-align:top;text-align:{{ S }}}
.iamr table.t tr{page-break-inside:avoid}
.iamr .num{text-align:{{ E }} !important;white-space:nowrap;direction:ltr}
.iamr .pill{display:inline-block;font-size:10px;font-weight:600;padding:1px 8px;border-radius:9px;border:1px solid}
.iamr .big{font-size:48px;font-weight:600;line-height:1;direction:ltr;text-align:{{ S }}}
.iamr .big small{font-size:20px}
.iamr .note{border-{{ S }}:3px solid #BF530B;background:#FFF6E0;padding:8px 10px;margin-top:8px}
.iamr .auto{display:inline-block;font-size:9px;font-weight:600;color:{{ brand.primary }};border:1px solid {{ brand.primary }};border-radius:8px;padding:0 6px;margin-{{ S }}:4px}
.iamr .head{border-bottom:2px solid {{ brand.ink }};padding-bottom:10px;margin-bottom:6px}
.iamr .sec{page-break-inside:avoid}
.iamr .brandline{height:4px;background:{{ brand.primary }};margin:0 0 14px}
.iamr .meta td{padding:1px 0;vertical-align:top}
.iamr .meta td.l{padding-{{ E }}:10px}
.iamr .bar-track{background:#EEF2F4;height:12px;padding:0}
.iamr .pos{color:#2D7A33;font-weight:600}.iamr .neg{color:#B42318;font-weight:600}
</style>
<div class="iamr" dir="{{ r.dir }}">
 <div class="brandline"></div>
 {% if r.internal_banner %}<div style="border:1.5px solid #B42318;color:#B42318;background:#FDECEA;padding:6px 10px;margin:0 0 12px;font-weight:700;font-size:11px;text-align:center">{{ r.internal_banner|e }}</div>{% endif %}
 <table style="width:100%" class="head"><tr>
  <td style="vertical-align:top">
   <img src="{{ brand.images.logo }}" alt="AlphaX" style="height:46px;width:auto;margin-bottom:8px">
   <div class="eyebrow">{{ brand.product }} · {{ t.internal_report if r.audience == "internal" else t.results_report }}</div>
   <h1>{{ t.title }}</h1>
   <div class="muted" style="font-size:13px">{{ r.entity|e }}</div>
  </td>
  <td style="vertical-align:top;width:270px">
   <table class="meta" style="font-size:10.5px">
    <tr><td class="muted l">{{ t.reference }}</td><td>{{ r.name|e }}</td></tr>
    <tr><td class="muted l">{{ t.assessment_date }}</td><td><span dir="ltr">{{ r.date|e }}</span></td></tr>
    <tr><td class="muted l">{{ t.assessed_by }}</td><td>{{ r.respondent|e }}{% if r.job_title %}{{ "، " if rtl else ", " }}{{ r.job_title|e }}{% endif %}</td></tr>
    {% if r.respondent_role %}<tr><td class="muted l">{{ t.perspective }}</td><td>{{ r.respondent_role|e }}</td></tr>{% endif %}
    {% if r.review_status_label %}<tr><td class="muted l">{{ t.review }}</td><td>{{ r.review_status_label|e }}</td></tr>{% endif %}
    <tr><td class="muted l">{{ t.framework }}</td><td>{{ t.framework_value }}</td></tr>
    <tr><td class="muted l">{{ t.questions }}</td><td>{{ r.questions_text|e }}</td></tr>
   </table>
  </td></tr></table>

 {% if r.show.summary %}
 <div class="sec">
 <h2><span class="k">{{ k() }}</span>{{ t.exec_summary }}</h2>
 <table style="width:100%"><tr>
  <td style="width:190px;vertical-align:top">
   <div class="big">{{ "%g"|format(r.overall) }}<small>%</small></div>
   <div style="margin-top:6px"><span class="pill" style="color:{{ r.level_color }};border-color:{{ r.level_color }}">{{ r.level_label|e }}</span></div>
   <div class="muted" style="margin-top:6px;font-size:10.5px">{{ r.points_text|e }}</div>
  </td>
  <td style="vertical-align:top">
   <p style="margin:0 0 6px">{{ r.interpretation|e }}</p>
   {% if r.strongest %}<p class="muted" style="margin:0 0 6px">{{ t.strongest }}: <b style="color:{{ brand.ink }}">{{ r.strongest.title|e }}</b> (<span dir="ltr">{{ "%g"|format(r.strongest.pct) }}%</span>).
   {{ t.weakest }}: <b style="color:{{ brand.ink }}">{{ r.weakest.title|e }}</b> (<span dir="ltr">{{ "%g"|format(r.weakest.pct) }}%</span>).
   {{ r.findings_text|e }} {{ r.na_text|e }}</p>{% endif %}
   {%- set mk = [[r.overall, 0.5]|max, 99.5]|min -%}
   <table style="width:100%;border-collapse:collapse;table-layout:fixed;margin-top:10px"><tr>
    <td style="width:{{ mk }}%;padding:0;height:10px"></td>
    <td style="padding:0;font-size:10px;line-height:10px;color:{{ brand.ink }};text-align:{{ S }}"><span style="position:relative;{{ S }}:-4px">&#9660;</span></td>
   </tr></table>
   <table style="width:100%;border-collapse:collapse;table-layout:fixed;margin-top:1px"><tr>
    {% for b in r.scale %}<td style="width:{{ b.width }}%;height:8px;line-height:8px;font-size:1px;background:{{ b.color }};padding:0">&nbsp;</td>{% endfor %}
   </tr><tr>
    {% for b in r.scale %}<td style="font-size:8.5px;color:#586976;padding:3px 0 0;text-align:{{ S }}"><span dir="ltr">{{ "%g"|format(b.from) }}%</span> {{ b.label|e }}</td>{% endfor %}
   </tr></table>
   {% if r.gating_note %}<div class="note">{{ r.gating_note|e }}</div>{% endif %}
  </td></tr></table>
 </div>
 {% endif %}

 {% if r.show.sections %}
 <div>
 <h2><span class="k">{{ k() }}</span>{{ t.results_by_section }}</h2>
 {% if rtl %}
 <table style="width:100%;border-collapse:collapse;margin-bottom:6px">
  {% for s in r.sections %}
  <tr>
   <td style="width:42%;padding:3px 0 3px 8px;font-size:10.5px">{{ s.title|e }}</td>
   <td style="padding:3px 0"><table style="width:100%;border-collapse:collapse;table-layout:fixed"><tr>
     <td style="width:{{ [s.pct, 0.5]|max }}%;height:12px;background:{{ s.color }};padding:0;font-size:1px">&nbsp;</td>
     <td class="bar-track" style="font-size:1px">&nbsp;</td></tr></table></td>
   <td class="num" style="width:52px;padding:3px 6px 3px 0;font-size:10px">{{ "%g"|format(s.pct) }}%</td>
  </tr>
  {% endfor %}
 </table>
 {% else %}
 <div style="text-align:center">{{ section_bar_svg(r) }}</div>
 {% endif %}
 <table class="t">
  <thead><tr><th>#</th><th>{{ t.section }}</th><th class="num">{{ t.points }}</th><th class="num">{{ t.score }}</th><th>{{ t.maturity }}</th></tr></thead>
  <tbody>
  {% for s in r.sections %}
   <tr><td>{{ loop.index }}</td><td>{{ s.title|e }}</td><td class="num">{{ "%g"|format(s.points) }} / {{ "%g"|format(s.max_points) }}</td><td class="num">{{ "%g"|format(s.pct) }}%</td>
   <td><span class="pill" style="color:{{ s.color }};border-color:{{ s.color }}">{{ s.level_label|e }}</span></td></tr>
  {% endfor %}
   <tr><td></td><td><b>{{ t.overall }}</b></td><td class="num"><b>{{ "%g"|format(r.points) }} / {{ "%g"|format(r.max_points) }}</b></td><td class="num"><b>{{ "%g"|format(r.overall) }}%</b></td>
   <td><span class="pill" style="color:{{ r.level_color }};border-color:{{ r.level_color }}">{{ r.level_label|e }}</span></td></tr>
  </tbody></table>
 </div>
 {% endif %}

 {% if r.benchmark %}
 <div class="sec">
 <h2><span class="k">{{ k() }}</span>{{ t.benchmark }}</h2>
 {% if r.benchmark.available %}
  {%- set bo = r.benchmark.overall -%}
  <p style="margin:0 0 4px"><b>{{ r.benchmark.percentile_text|e }}</b>
   {{ t.your_score }}: <span dir="ltr">{{ "%g"|format(bo.value) }}%</span> · {{ t.peer_median }}: <span dir="ltr">{{ "%g"|format(bo.median) }}%</span> · {{ t.peer_iqr }}: <span dir="ltr">{{ "%g"|format(bo.p25) }}–{{ "%g"|format(bo.p75) }}%</span></p>
  <table class="t">
   <thead><tr><th>{{ t.section }}</th><th class="num">{{ t.your_score }}</th><th class="num">{{ t.peer_median }}</th><th class="num">{{ t.peer_iqr }}</th><th class="num">{{ t.vs_median }}</th></tr></thead>
   <tbody>
   {% for s in r.benchmark.sections %}
    <tr><td>{{ s.title|e }}</td><td class="num">{{ "%g"|format(s.value) }}%</td><td class="num">{{ "%g"|format(s.median) }}%</td><td class="num">{{ "%g"|format(s.p25) }}–{{ "%g"|format(s.p75) }}%</td>
    <td class="num"><span class="{{ 'pos' if s.delta >= 0 else 'neg' }}">{{ "%+g"|format(s.delta) }}</span></td></tr>
   {% endfor %}
   </tbody></table>
  <p class="muted" style="font-size:9.5px;margin-top:4px">{{ r.benchmark.note|e }}</p>
 {% else %}
  <p class="muted">{{ r.benchmark.message|e }}</p>
 {% endif %}
 </div>
 {% endif %}

 {% if r.show.findings %}
 <h2><span class="k">{{ k() }}</span>{{ t.key_findings }}</h2>
 {% if r.findings %}
 <table class="t"><thead><tr><th style="width:42px">#</th><th>{{ t.area }}</th><th style="width:75px">{{ t.answer }}</th><th>{{ t.current_practice }}</th><th style="width:70px">{{ t.priority }}</th></tr></thead><tbody>
 {% for f in r.findings %}
  <tr><td>{{ f.code|e }}</td><td><b>{{ f.label|e }}</b><div class="muted" style="font-size:10px">{{ f.section_title|e }}</div></td><td>{{ f.answer_letter|e }} · {{ f.answer_level|e }}</td><td>{{ f.statement|e }}{% if f.auto_note %}<div class="muted" style="font-size:9.5px;margin-top:3px"><span class="auto">{{ t.auto_calc }}</span> {{ f.auto_note|e }}</div>{% endif %}{% if f.comment %}<div class="muted" style="font-size:10px;margin-top:3px">{{ t.comment }}: {{ f.comment|e }}</div>{% endif %}</td>
  <td style="color:{{ '#B42318' if f.priority == 'Immediate' else '#BF530B' }};font-weight:600">{{ f.priority_label|e }}</td></tr>
 {% endfor %}</tbody></table>
 {% else %}<p class="muted">{{ t.no_findings }}</p>{% endif %}
 {% endif %}

 {% if r.show.roadmap %}
 <h2><span class="k">{{ k() }}</span>{{ t.roadmap }}</h2>
 {% if r.actions %}
 <table class="t"><thead><tr><th style="width:42px">#</th><th>{{ t.area }}</th><th>{{ t.target_practice }}</th><th style="width:110px">{{ t.owner }}</th><th style="width:80px">{{ t.timeframe }}</th></tr></thead><tbody>
 {% for a in r.actions %}
  <tr><td>{{ a.code|e }}</td><td><b>{{ a.label|e }}</b><div class="muted" style="font-size:10px">{{ a.answer_letter|e }} {{ "←" if rtl else "→" }} {{ a.target_letter|e }} ({{ a.target_level|e }})</div></td><td>{{ a.next_statement|e }}</td><td>{{ a.owner|e }}</td>
  <td><span style="color:{{ {'Immediate':'#B42318','High':'#BF530B','Medium':'#9A6F00'}.get(a.priority, '#2D7A33') }};font-weight:600">{{ a.priority_label|e }}</span><div class="muted" style="font-size:10px">{{ a.timeframe|e }}</div></td></tr>
 {% endfor %}</tbody></table>
 {% else %}<p class="muted">{{ t.no_actions }}</p>{% endif %}
 {% endif %}

 {% if r.show.responses %}
 <h2><span class="k">{{ k() }}</span>{{ t.detailed }}</h2>
 <table class="t"><thead><tr><th style="width:42px">#</th><th>{{ t.question }}</th><th style="width:85px">{{ t.answer }}</th><th class="num" style="width:45px">{{ t.pts }}</th></tr></thead><tbody>
 {% for a in r.answers %}
  <tr><td>{{ a.code|e }}</td><td>{{ a.question|e }}<div class="muted" style="font-size:10px;margin-top:2px">{{ a.statement|e }}</div>{% if a.auto_note %}<div class="muted" style="font-size:9.5px;margin-top:2px"><span class="auto">{{ t.auto_calc }}</span> {{ a.auto_note|e }}</div>{% endif %}{% if a.comment %}<div style="font-size:10px;margin-top:2px"><i>{{ t.comment }}:</i> {{ a.comment|e }}</div>{% endif %}</td>
  <td>{{ a.answer_letter|e }}{% if a.answer_level and a.answer != "N/A" %} · {{ a.answer_level|e }}{% endif %}</td><td class="num">{{ "%g"|format(a.points) if a.answer != "N/A" else "–" }}</td></tr>
 {% endfor %}</tbody></table>
 {% endif %}

 {% if r.reviewer_comments and r.review_status in ("Reviewed", "Approved") %}
 <h2><span class="k">{{ k() }}</span>{{ t.reviewer_comments }}</h2>
 <p>{{ r.reviewer_comments|e }}</p>
 {% endif %}

 {% if r.show.scoring_method %}
 <h2><span class="k">{{ k() }}</span>{{ t.scoring_method }}</h2>
 <p class="muted" style="font-size:10.5px">{{ r.scoring_text|e }}</p>
 {% endif %}
</div>

<div id="footer-html">
 {% if rtl %}<style>{{ arabic_font_css() }}</style>{% endif %}
 <table dir="{{ r.dir }}" style="width:100%;font-family:{% if rtl %}'IAM Arabic',{% endif %}Helvetica,Arial,sans-serif;font-size:8.5px;color:#5A6562;border-top:1px solid #D9E1E6;padding-top:4px;direction:{{ r.dir }}">
  <tr>
   <td style="width:90px;vertical-align:middle;text-align:{{ S }}"><img src="{{ brand.images.company_logo }}" style="height:22px;width:auto" alt="IRSAA"></td>
   <td style="vertical-align:middle;text-align:{{ S }}">{{ brand.product_title }} · {{ brand.company }} · {{ brand.support_email }}<br>{{ t.internal_report if r.audience == "internal" else t.confidential }} – {{ r.entity|e }} · {{ r.name|e }}</td>
   <td style="text-align:{{ E }};vertical-align:middle;white-space:nowrap">{{ t.page }} <span class="page"></span> {{ t.of }} <span class="topage"></span></td>
  </tr>
 </table>
</div>
